#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Basis {
    Equation,
    Nomograph,
    Hy8,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Quantity {
    Form1HwOverD,
    SubmergedHwOverD,
    CriticalHeadOverD,
    CriticalFlowFactor,
    HwOverD,
    Headwater,
    CriticalDepth,
    BarrelLoss,
}

/// Design inputs in feet, cubic feet per second, and plain ratios.
#[derive(Clone, Copy, Debug)]
pub struct Design {
    pub circular: bool,
    pub code: u8,
    pub rise: f64,
    pub span: Option<f64>,
    pub slope: f64,
    pub length: f64,
    pub manning: Option<f64>,
    pub ke: f64,
    pub discharge: f64,
    pub tailwater: f64,
}

#[derive(Clone, Copy, Debug)]
pub struct PublishedRow {
    pub example: &'static str,
    pub pdf_page: u16,
    pub page_label: &'static str,
    pub basis: Basis,
    pub quantity: Quantity,
    /// Design inputs, or `None` for an appendix equation row.
    pub design: Option<Design>,
    /// Appendix equation inputs as printed: x or dc/D or Ap/A, then Hc/D or yh/D.
    pub printed_inputs: [Option<f64>; 2],
    pub published: f64,
    pub tolerance: f64,
    pub equation_value: f64,
    pub within: bool,
}

